/* GORA 2.0 — clean frontend foundation + Members module
 * Uses Supabase Auth, RLS, and the GORA member RPCs. No demo records are generated.
 */
const $ = (id) => document.getElementById(id);
let db = null;
let authUser = null;
let profile = null;
let organizations = [];
let organization = null;
let branches = [];
let chamas = [];
let loanOfficers = [];
let customFields = [];
let membersPageIndex = 0;
const PAGE_SIZE = 50;
let memberSearch = '';
let memberStatusFilter = 'ALL';
let branchFilter = 'ALL';
let lastLoanFilter = 'ALL';
let selectedMemberIds = new Set();
let currentProfileId = null;
let currentProfileTab = 'Overview';

const money = (value) => new Intl.NumberFormat('en-KE',{style:'currency',currency:'KES',maximumFractionDigits:2}).format(Number(value||0));
const number = (value) => new Intl.NumberFormat('en-KE').format(Number(value||0));
const esc = (value) => String(value??'').replace(/[&<>"']/g,(c)=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeName = (value) => String(value||'').trim();
const initials = (value) => safeName(value).split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase()||'M';
const todayLocal = () => new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Nairobi',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const statusClass = (value) => ['pending','approved','active','rejected','inactive','exited','blocked'].includes(String(value||'').toLowerCase())?String(value).toLowerCase():'inactive';
const statusPill = (value) => `<span class="pill ${statusClass(value)}">${esc(String(value||'UNKNOWN').replaceAll('_',' '))}</span>`;
const setMessage = (id,text,isError=true) => { const el=$(id); if(el){el.textContent=text||'';el.style.color=isError?'var(--red)':'var(--green)';} };
function toast(message,type='success'){const root=$('toastRoot');const item=document.createElement('div');item.className=`toast ${type==='error'?'error':type==='success'?'success':''}`;item.textContent=message;root.appendChild(item);setTimeout(()=>item.remove(),4200);}
async function safeQuery(query){const {data,error}=await query;if(error)throw error;return data;}
function saveConnection(){localStorage.setItem('gora2_url',$('supabaseUrl').value.trim());localStorage.setItem('gora2_key',$('supabaseKey').value.trim());localStorage.setItem('gora_url',$('supabaseUrl').value.trim());localStorage.setItem('gora_key',$('supabaseKey').value.trim());}
function connect(){const url=localStorage.getItem('gora2_url'),key=localStorage.getItem('gora2_key');if(!url||!key||!window.supabase)return false;db=window.supabase.createClient(url,key);return true;}
function userRoleRank(code){return ({SUPER_ADMIN:1,MANAGER:2,ACCOUNTANT:3,CASHIER:4,LOAN_OFFICER:5,AUDITOR:6})[code]||99;}
async function loadOrganizations(){
 const roles=await safeQuery(db.from('user_roles').select('organization_id,role_id,is_active').eq('user_id',authUser.id).eq('is_active',true));
 if(!roles?.length)throw new Error('No active GORA organisation role was found for this account.');
 const roleIds=[...new Set(roles.map(x=>x.role_id))];
 const roleRows=await safeQuery(db.from('roles').select('id,role_code,role_name').in('id',roleIds));
 const roleMap=new Map(roleRows.map(x=>[x.id,x]));
 const orgIds=[...new Set(roles.map(x=>x.organization_id))];
 const orgRows=await safeQuery(db.from('organizations').select('id,name,currency_code,timezone').in('id',orgIds));
 organizations=orgRows.map(org=>{
   const matches=roles.filter(r=>r.organization_id===org.id).map(r=>roleMap.get(r.role_id)).filter(Boolean).sort((a,b)=>userRoleRank(a.role_code)-userRoleRank(b.role_code));
   return {...org,roleCode:matches[0]?.role_code||'STAFF',roleName:matches[0]?.role_name||'Staff'};
 });
 organization=organizations[0];
 if(organizations.length>1){$('organizationSelect').classList.remove('hidden');$('organizationSelect').innerHTML=organizations.map(o=>`<option value="${o.id}">${esc(o.name)}</option>`).join('');$('organizationSelect').value=organization.id;}
 else $('organizationSelect').classList.add('hidden');
}
async function loadReferenceData(){
 const [branchRows,chamaRows,fieldRows]=await Promise.all([
  safeQuery(db.from('branches').select('id,branch_code,branch_name,status').eq('organization_id',organization.id).eq('status','ACTIVE').order('branch_name')),
  safeQuery(db.from('chama_groups').select('id,group_code,group_name,status').eq('organization_id',organization.id).eq('status','ACTIVE').order('group_name')),
  safeQuery(db.from('gora_member_custom_fields').select('id,field_key,label,field_type,options,is_required,is_active,display_order').eq('organization_id',organization.id).eq('is_active',true).order('display_order'))
 ]);
 branches=branchRows||[];chamas=chamaRows||[];customFields=fieldRows||[];
 const roleRows=await safeQuery(db.from('user_roles').select('user_id,role_id').eq('organization_id',organization.id).eq('is_active',true).lte('starts_on',todayLocal()).or(`expires_on.is.null,expires_on.gte.${todayLocal()}`));
 const roleIds=[...new Set(roleRows.map(x=>x.role_id))];
 const roles=roleIds.length?await safeQuery(db.from('roles').select('id,role_code').in('id',roleIds)):[];
 const officerRoleIds=roles.filter(x=>x.role_code==='LOAN_OFFICER').map(x=>x.id);
 const officerIds=roleRows.filter(x=>officerRoleIds.includes(x.role_id)).map(x=>x.user_id);
 const profiles=officerIds.length?await safeQuery(db.from('profiles').select('id,full_name,phone').in('id',[...new Set(officerIds)]).order('full_name')):[];
 loanOfficers=profiles||[];
}
function roleCanManage(){return ['SUPER_ADMIN','MANAGER'].includes(profile?.roleCode);}
function roleCanApprove(){return roleCanManage();}
async function finishLogin(user){
 authUser=user;
 const p=await safeQuery(db.from('profiles').select('full_name,phone,active').eq('id',user.id).single());
 if(!p?.active)throw new Error('Your GORA staff profile is inactive. Please contact the administrator.');
 profile={...p,userId:user.id};
 await loadOrganizations();
 profile.roleCode=organization.roleCode;profile.roleName=organization.roleName;
 $('signedUserName').textContent=profile.full_name||user.email||'GORA staff';$('signedUserRole').textContent=profile.roleName||'Staff';$('userAvatar').textContent=initials(profile.full_name);
 $('loginScreen').classList.add('hidden');$('appShell').classList.remove('hidden');
 await loadReferenceData();
 await renderMembers();
}
$('saveConnection').addEventListener('click',()=>{saveConnection();toast(connect()?'Connection saved on this device.':'Enter both the project URL and public key.');});
$('loginForm').addEventListener('submit',async(e)=>{e.preventDefault();$('loginMessage').textContent='';if(!connect()){setMessage('loginMessage','Save your Supabase connection settings first.');return;}try{const {data,error}=await db.auth.signInWithPassword({email:$('loginEmail').value.trim(),password:$('loginPassword').value});if(error)throw error;await finishLogin(data.user);}catch(err){setMessage('loginMessage',err.message||'Unable to sign in.');}});
$('signOut').addEventListener('click',async()=>{if(db)await db.auth.signOut();location.reload();});$('mobileMenu').addEventListener('click',()=>$('sidebar').classList.toggle('open'));
$('organizationSelect').addEventListener('change',async()=>{organization=organizations.find(o=>o.id===$('organizationSelect').value)||organizations[0];profile.roleCode=organization.roleCode;profile.roleName=organization.roleName;await loadReferenceData();membersPageIndex=0;selectedMemberIds.clear();await renderMembers();});
$('navigation').addEventListener('click',async(e)=>{const button=e.target.closest('[data-module]');if(!button)return;document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x===button));$('sidebar').classList.remove('open');const moduleName=button.dataset.module;$('pageTitle').textContent=moduleName;if(moduleName==='Members'){await renderMembers();return;}renderFutureModule(moduleName);});
function renderFutureModule(moduleName){$('pageContent').innerHTML=`<section class="future-module"><div class="future-icon">✦</div><h2>${esc(moduleName)}</h2><p>This module is scheduled in the GORA 2.0 build order. We are finishing and testing Members first, then we will connect this module to the same database and navigation.</p><div class="note-box">The dashboard is intentionally reserved for the final stage, after all modules and financial data are connected.</div><button class="btn btn-primary" type="button" onclick="document.querySelector('[data-module=Members]').click()">Return to Members</button></section>`;}
function statCard(label,value,caption,tone,icon){return `<div class="stat-card stat-${tone}"><div class="stat-top"><span class="stat-icon">${icon}</span>${esc(label)}</div><strong>${value}</strong><small>${esc(caption)}</small></div>`;}
function buildToolbar(){return `<div class="toolbar"><input id="memberSearch" type="search" placeholder="Search name, number, mobile, email, address, officer or custom field…" value="${esc(memberSearch)}"><select id="memberStatusFilter"><option value="ALL">All member statuses</option>${['PENDING','APPROVED','ACTIVE','REJECTED','INACTIVE','EXITED'].map(s=>`<option value="${s}" ${memberStatusFilter===s?'selected':''}>${s.replaceAll('_',' ')}</option>`).join('')}</select><select id="branchFilter"><option value="ALL">All branches</option>${branches.map(b=>`<option value="${b.id}" ${branchFilter===b.id?'selected':''}>${esc(b.branch_name)}</option>`).join('')}</select><select id="lastLoanFilter"><option value="ALL">All last loan statuses</option><option value="FULLY_PAID" ${lastLoanFilter==='FULLY_PAID'?'selected':''}>Last loan fully paid</option><option value="ACTIVE" ${lastLoanFilter==='ACTIVE'?'selected':''}>Last loan active</option><option value="DEFAULTED" ${lastLoanFilter==='DEFAULTED'?'selected':''}>Last loan defaulted</option><option value="NO_LOAN" ${lastLoanFilter==='NO_LOAN'?'selected':''}>No loan history</option><option value="CANCELLED" ${lastLoanFilter==='CANCELLED'?'selected':''}>Last loan cancelled</option></select><button class="btn btn-soft" id="resetMemberFilters" type="button">Reset</button></div>`;}
async function memberCounts(){
 const [all,pending,approved,active]=await Promise.all([
  db.from('members').select('id',{count:'exact',head:true}).eq('organization_id',organization.id),
  db.from('members').select('id',{count:'exact',head:true}).eq('organization_id',organization.id).eq('status','PENDING'),
  db.from('members').select('id',{count:'exact',head:true}).eq('organization_id',organization.id).eq('status','APPROVED'),
  db.from('members').select('id',{count:'exact',head:true}).eq('organization_id',organization.id).eq('status','ACTIVE')
 ]);
 for(const r of [all,pending,approved,active])if(r.error)throw r.error;
 return {all:all.count||0,pending:pending.count||0,approved:approved.count||0,active:active.count||0};
}
async function renderMembers(){
 $('pageTitle').textContent='Members';$('pageContent').innerHTML='<div class="loading-panel">Loading member records…</div>';
 try{
  const [counts,rows]=await Promise.all([memberCounts(),safeQuery(db.rpc('search_members_v2',{_organization_id:organization.id,_search:memberSearch||null,_member_status:memberStatusFilter,_branch_id:branchFilter==='ALL'?null:branchFilter,_last_loan_status:lastLoanFilter,_limit:PAGE_SIZE,_offset:membersPageIndex*PAGE_SIZE}))]);
  const total=rows?.[0]?.total_count||0;
  const restrictedCount=await safeQuery(db.from('gora_member_restrictions').select('id',{count:'exact'}).eq('organization_id',organization.id).eq('is_active',true).lte('starts_on',todayLocal()).or(`expires_on.is.null,expires_on.gte.${todayLocal()}`));
  const pageRows=rows||[];
  const pagePhotoUrls={};
  await Promise.all(pageRows.filter(m=>m.member_photo_path).map(async m=>{const {data,error}=await db.storage.from('gora-member-documents').createSignedUrl(m.member_photo_path,180);if(!error)pagePhotoUrls[m.member_id]=data.signedUrl;}));
  const tableRows=pageRows.map(m=>{
   const checked=selectedMemberIds.has(m.member_id)?'checked':'';
   const branch=branches.find(b=>b.id===m.branch_id)?.branch_name||'—';
   return `<tr><td><input type="checkbox" class="member-select" data-id="${m.member_id}" ${checked} aria-label="Select ${esc(m.full_name)}"></td><td><div class="member-cell">${pagePhotoUrls[m.member_id]?`<img class="member-photo" src="${pagePhotoUrls[m.member_id]}" alt="">`:`<div class="member-photo">${esc(initials(m.full_name))}</div>`}<div><b>${esc(m.business_name||m.full_name)}</b><small>${esc(m.first_name&&m.last_name?m.first_name+' '+m.last_name:m.full_name)}</small></div></div></td><td><span class="member-number">${esc(m.member_number||'Pending number')}</span></td><td>${esc(m.phone||'—')}<small class="muted">${esc(m.email||'')}</small></td><td>${esc(branch)}</td><td>${statusPill(m.status)}</td><td>${statusPill(m.last_loan_status)}</td><td><button class="icon-btn open-member" data-id="${m.member_id}">View profile</button></td></tr>`;
  }).join('');
  $('pageContent').innerHTML=`<div class="page-heading"><div><h2>Members registry</h2><p>Register, manage and review GORA members and borrowers.</p></div><div class="heading-actions"><button class="btn btn-soft" id="numberSettingsBtn">Member number format</button><button class="btn btn-purple" id="customFieldsBtn">Custom fields</button><button class="btn btn-teal" id="bulkImportBtn">Bulk CSV import</button><button class="btn btn-primary" id="newMemberBtn">＋ Add member</button></div></div>
  <div class="stats-grid">${statCard('All members',number(counts.all),'All member records','blue','♙')}${statCard('Pending approval',number(counts.pending),'Awaiting review','orange','◷')}${statCard('Approved',number(counts.approved),'Approved member records','purple','✓')}${statCard('Active restrictions',number(restrictedCount.length||0),'Current borrower restrictions','red','⚑')}</div>
  <div class="panel"><div class="panel-head"><div><h3>Member directory</h3><p>Search and filter records. Select members to export or contact.</p></div><div class="heading-actions"><button class="btn btn-neutral" id="exportMembersBtn">Export CSV</button><button class="btn btn-soft" id="emailSelectedBtn">Email selected</button><button class="btn btn-soft" id="smsSelectedBtn">SMS selected</button></div></div>${buildToolbar()}<div class="table-wrap"><table class="data-table"><thead><tr><th><input type="checkbox" id="selectCurrentPage" aria-label="Select current page"></th><th>Member / borrower</th><th>Unique number</th><th>Contact</th><th>Branch</th><th>Member status</th><th>Last loan</th><th>Action</th></tr></thead><tbody>${tableRows||`<tr><td colspan="8"><div class="empty-state">No members match these filters. Add a member or change your search.</div></td></tr>`}</tbody></table></div><div class="pagination"><span>Showing ${total?membersPageIndex*PAGE_SIZE+1:0}–${Math.min((membersPageIndex+1)*PAGE_SIZE,total)} of ${number(total)} members</span><div class="pagination-actions"><button class="btn btn-neutral" id="prevMemberPage" ${membersPageIndex===0?'disabled':''}>← Previous</button><button class="btn btn-neutral" id="nextMemberPage" ${((membersPageIndex+1)*PAGE_SIZE>=total)?'disabled':''}>Next →</button></div></div></div>
  <div class="note-box">Member numbers are generated when a pending member is approved. CSV export is Excel-compatible. SMS, email and WhatsApp actions open the device/app composer; automated bulk delivery requires a messaging provider connection.</div>`;
  $('memberSearch').addEventListener('input',debounce(async(e)=>{memberSearch=e.target.value.trim();membersPageIndex=0;await renderMembers();},300));
  $('memberStatusFilter').addEventListener('change',async(e)=>{memberStatusFilter=e.target.value;membersPageIndex=0;await renderMembers();});
  $('branchFilter').addEventListener('change',async(e)=>{branchFilter=e.target.value;membersPageIndex=0;await renderMembers();});
  $('lastLoanFilter').addEventListener('change',async(e)=>{lastLoanFilter=e.target.value;membersPageIndex=0;await renderMembers();});
  $('resetMemberFilters').onclick=async()=>{memberSearch='';memberStatusFilter='ALL';branchFilter='ALL';lastLoanFilter='ALL';membersPageIndex=0;await renderMembers();};
  $('prevMemberPage').onclick=async()=>{membersPageIndex=Math.max(0,membersPageIndex-1);await renderMembers();};
  $('nextMemberPage').onclick=async()=>{membersPageIndex++;await renderMembers();};
  $('newMemberBtn').onclick=()=>openRegistrationModal();$('bulkImportBtn').onclick=()=>openCsvImportModal();$('customFieldsBtn').onclick=()=>openCustomFieldsModal();$('numberSettingsBtn').onclick=()=>openNumberSettingsModal();$('exportMembersBtn').onclick=()=>exportMembersCsv();
  $('selectCurrentPage').onchange=(e)=>{pageRows.forEach(m=>e.target.checked?selectedMemberIds.add(m.member_id):selectedMemberIds.delete(m.member_id));renderMembers();};
  document.querySelectorAll('.member-select').forEach(el=>el.onchange=()=>{el.checked?selectedMemberIds.add(el.dataset.id):selectedMemberIds.delete(el.dataset.id);});
  document.querySelectorAll('.open-member').forEach(el=>el.onclick=()=>openMemberProfile(el.dataset.id));
  $('emailSelectedBtn').onclick=()=>contactSelected('email');$('smsSelectedBtn').onclick=()=>contactSelected('sms');
 }catch(err){$('pageContent').innerHTML=`<div class="warning-box"><b>Members could not be loaded.</b><br>${esc(err.message||'Database request failed')}<br><br>Check your staff role and the Supabase connection, then refresh.</div>`;}
}
function debounce(fn,ms){let timer;return(...args)=>{clearTimeout(timer);timer=setTimeout(()=>fn(...args),ms);};}
function openModal(title,subtitle,body,footer='',wide=false){const root=$('modalRoot');root.innerHTML=`<div class="modal-backdrop" id="modalBackdrop"><section class="modal ${wide?'modal-wide':''}" role="dialog" aria-modal="true"><header class="modal-header"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button class="modal-close" id="modalClose" type="button" aria-label="Close">×</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;$('modalClose').onclick=closeModal;$('modalBackdrop').addEventListener('click',(e)=>{if(e.target.id==='modalBackdrop')closeModal();});}
function closeModal(){$('modalRoot').innerHTML='';}
function field(label,name,type='text',value='',options={}){const required=options.required?'required':'';const full=options.full?'full-span':'';const placeholder=options.placeholder?`placeholder="${esc(options.placeholder)}"`:'';if(type==='select')return `<div class="form-field ${full}"><label>${esc(label)}<select name="${esc(name)}" ${required}>${(options.choices||[]).map(o=>`<option value="${esc(o.value)}" ${String(o.value)===String(value)?'selected':''}>${esc(o.label)}</option>`).join('')}</select></label></div>`;if(type==='textarea')return `<div class="form-field ${full}"><label>${esc(label)}<textarea name="${esc(name)}" rows="3" ${required} ${placeholder}>${esc(value)}</textarea></label></div>`;return `<div class="form-field ${full}"><label>${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${required} ${placeholder} ${options.accept?`accept="${options.accept}"`:''} ${options.className?`class="${options.className}"`:''}></label></div>`;}
function getFormData(form){return Object.fromEntries(new FormData(form).entries());}
function customFieldInput(f,value=''){if(f.field_type==='select'){const opts=(f.options||[]).map(x=>typeof x==='string'?{value:x,label:x}:x);return field(f.label,f.field_key,'select',value,{required:f.is_required,choices:[{value:'',label:'Select…'},...opts]});}if(f.field_type==='checkbox')return `<div class="form-field"><label class="check-row"><input type="checkbox" name="custom_${esc(f.field_key)}" ${f.is_required?'required':''} ${value==='true'||value===true?'checked':''}> ${esc(f.label)}${f.is_required?' *':''}</label></div>`;return field(f.label,f.field_key,f.field_type==='number'?'number':f.field_type==='date'?'date':'text',value,{required:f.is_required});}
function fileDocField(label,name){return `<div class="form-field"><label>${esc(label)}<input class="file-input" type="file" name="${name}" accept="image/jpeg,image/png,image/webp"></label><small class="small-note">Optional · JPG, PNG or WebP · max 5 MB</small></div>`;}function openRegistrationModal(){
 const branchChoices=[{value:'',label:'Choose branch (optional)'},...branches.map(b=>({value:b.id,label:b.branch_name}))];
 const chamaChoices=[{value:'',label:'No chama / assign later'},...chamas.map(g=>({value:g.id,label:g.group_name}))];
 const officerChoices=[{value:'',label:'Unassigned'},...loanOfficers.map(o=>({value:o.id,label:o.full_name}))];
 const body=`<form id="memberRegistrationForm"><div class="form-section"><h4>Borrower identity</h4><p>Enter both first and last name, or enter a business name.</p></div><div class="form-grid">${field('Title','title','select','',{choices:[{value:'',label:'Select title'},{value:'Mr',label:'Mr'},{value:'Mrs',label:'Mrs'},{value:'Ms',label:'Ms'},{value:'Miss',label:'Miss'},{value:'Dr',label:'Dr'},{value:'Other',label:'Other'}]})}${field('First name','first_name')}${field('Last name','last_name')}${field('Business name','business_name')}${field('Mobile / phone','phone','tel','')}${field('Email address','email','email')}${field('Date of birth','date_of_birth','date')}${field('Gender','gender','select','',{choices:[{value:'',label:'Select gender'},{value:'FEMALE',label:'Female'},{value:'MALE',label:'Male'},{value:'OTHER',label:'Other'},{value:'PREFER_NOT_TO_SAY',label:'Prefer not to say'}]})}${field('National ID number','national_id')}${field('Address','address','text','',{full:true})}${field('County','county')}${field('Town','town')}${field('Estate / village','estate')}${field('Occupation','occupation')}${field('Income source','income_source')}${field('Description / notes','description','textarea','',{full:true})}</div><div class="form-section"><h4>Branch, chama &amp; officer</h4><p>Optional assignments can be updated later by an authorised manager.</p></div><div class="form-grid">${field('Branch','branch_id','select',branches[0]?.id||'',{choices:branchChoices})}${field('Chama','chama_group_id','select','',{choices:chamaChoices})}${field('Loan officer','loan_officer_id','select','',{choices:officerChoices})}${field('Registration fee reference','registration_fee_reference','text','')}</div><div class="form-section"><h4>Next of kin</h4><p>Optional contact information.</p></div><div class="form-grid">${field('Next-of-kin full name','next_of_kin_name')}${field('Relationship','next_of_kin_relationship')}${field('Next-of-kin phone','next_of_kin_phone','tel')}</div><div class="form-section"><h4>Documents &amp; photos</h4><p>Documents are stored in a private GORA bucket.</p></div><div class="form-grid">${fileDocField('Borrower photo','member_photo')}${fileDocField('ID front','id_front')}${fileDocField('ID back','id_back')}${fileDocField('Next-of-kin photo','next_of_kin_photo')}</div><div class="form-section"><h4>Additional files</h4><p>Optional supporting documents (PDF, Word, Excel, text or image) · max 10 MB each.</p></div><div class="form-field full-span"><label>Attach files<input class="file-input" type="file" name="other_files" multiple accept=".pdf,.doc,.docx,.xls,.xlsx,.txt,image/jpeg,image/png,image/webp"></label></div>${customFields.length?`<div class="form-section"><h4>Custom fields</h4><p>Fields configured by GORA management.</p></div><div class="form-grid">${customFields.map(f=>customFieldInput(f)).join('')}</div>`:''}<div class="form-section"><h4>Member declarations</h4><p>Confirm these with the member before registration.</p></div><label class="check-row"><input type="checkbox" name="savings_agreement_accepted" required> Member has accepted the savings agreement.</label><label class="check-row"><input type="checkbox" name="information_declaration_accepted" required> Member confirms the information provided is correct.</label></form>`;
 openModal('Register new member','Create a borrower record in GORA 2.0',body,`<button class="btn btn-neutral" id="cancelRegistration">Cancel</button><button class="btn btn-primary" id="submitRegistration">Save member</button>`,true);
 $('cancelRegistration').onclick=closeModal;
 $('submitRegistration').onclick=async()=>{const form=$('memberRegistrationForm');if(!form.reportValidity())return;const data=getFormData(form);const first=safeName(data.first_name),last=safeName(data.last_name),business=safeName(data.business_name);if(!(first&&last)&&!business){toast('Enter first and last name, or a business name.','error');return;}const custom={};customFields.forEach(f=>{const el=form.elements[f.field_key]||form.elements[`custom_${f.field_key}`];if(f.field_type==='checkbox')custom[f.field_key]=!!el?.checked;else if(el&&el.value!=='')custom[f.field_key]=el.value;});const memberId=crypto.randomUUID();const payload={...data,custom_field_values:custom,savings_agreement_accepted:!!form.elements.savings_agreement_accepted.checked,information_declaration_accepted:!!form.elements.information_declaration_accepted.checked};delete payload.member_photo;delete payload.id_front;delete payload.id_back;delete payload.next_of_kin_photo;delete payload.other_files;payload.branch_id=payload.branch_id||null;payload.chama_group_id=payload.chama_group_id||null;payload.loan_officer_id=payload.loan_officer_id||null;try{$('submitRegistration').disabled=true;$('submitRegistration').textContent='Saving…';const files=[['member_photo','member-photo'],['id_front','id-front'],['id_back','id-back'],['next_of_kin_photo','next-of-kin-photo']];for(const [inputName,base] of files){const file=form.elements[inputName].files?.[0];if(file){const path=await uploadMemberDocument(memberId,base,file);const fieldName={member_photo:'member_photo_path',id_front:'national_id_front_path',id_back:'national_id_back_path',next_of_kin_photo:'next_of_kin_photo_path'}[inputName];payload[fieldName]=path;}}const {error}=await db.rpc('register_member_v3',{_member_id:memberId,_organization_id:organization.id,_payload:payload});if(error)throw error;let extraFilesFailed=0;const extraFiles=[...(form.elements.other_files.files||[])];for(const file of extraFiles){try{await saveGeneralMemberDocument(memberId,file,'OTHER');}catch(docErr){extraFilesFailed++;}}closeModal();toast(extraFilesFailed?`Member registered; ${extraFilesFailed} supporting file(s) did not upload.`:'Member registered and added to the Members registry. Approval and member number are pending.',extraFilesFailed?'error':'success');membersPageIndex=0;await renderMembers();}catch(err){$('submitRegistration').disabled=false;$('submitRegistration').textContent='Save member';toast(err.message||'Member registration failed.','error');}};
}
async function uploadMemberDocument(memberId,base,file){if(file.size>5*1024*1024)throw new Error(`${file.name} is over the 5 MB limit.`);const mimeMap={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'};const ext=mimeMap[file.type];if(!ext)throw new Error('Use a JPG, PNG or WebP image.');const path=`${organization.id}/${memberId}/${base}.${ext}`;const {error}=await db.storage.from('gora-member-documents').upload(path,file,{upsert:false,contentType:file.type});if(error)throw error;return path;}
async function saveGeneralMemberDocument(memberId,file,documentType='OTHER'){
 if(file.size>10*1024*1024)throw new Error(`${file.name} is over the 10 MB limit.`);
 const allowed=new Set(['application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','text/plain','image/jpeg','image/png','image/webp']);
 if(!allowed.has(file.type))throw new Error(`File type is not allowed: ${file.name}`);
 const ext=(file.name.split('.').pop()||'file').toLowerCase().replace(/[^a-z0-9]/g,'').slice(0,8)||'file';
 const path=`${organization.id}/${memberId}/attachment-${crypto.randomUUID()}.${ext}`;
 const {error:uploadError}=await db.storage.from('gora-member-documents').upload(path,file,{upsert:false,contentType:file.type});if(uploadError)throw uploadError;
 const {error:metaError}=await db.from('gora_member_documents').insert({organization_id:organization.id,member_id:memberId,document_type:documentType,original_filename:file.name,storage_path:path,mime_type:file.type,file_size:file.size,uploaded_by:authUser.id});if(metaError)throw metaError;
 return path;
}
async function openNumberSettingsModal(){if(!roleCanManage()){toast('Only a manager or super administrator can change this format.','error');return;}let settings;try{settings=await safeQuery(db.from('gora_member_number_settings').select('prefix,format_pattern,sequence_width').eq('organization_id',organization.id).maybeSingle());}catch(e){toast(e.message,'error');return;}const body=`<form id="numberSettingsForm"><div class="form-grid">${field('Number prefix','prefix','text',settings?.prefix||'GORA-M',{required:true})}${field('Sequence width','sequence_width','number',settings?.sequence_width||6,{required:true})}${field('Format pattern','format_pattern','text',settings?.format_pattern||'{PREFIX}-{SEQ}',{required:true,full:true,placeholder:'{PREFIX}-{YYYY}-{SEQ}'})}</div><div class="note-box">Available tokens: <b>{PREFIX}</b>, <b>{YYYY}</b>, <b>{YY}</b>, <b>{MM}</b>, <b>{SEQ}</b>.<br>Example: prefix <b>GORA</b>, pattern <b>{PREFIX}-{YYYY}-{SEQ}</b>, width <b>5</b> → GORA-2026-00001.</div><p class="small-note">The sequence is generated securely by the database when a member is approved. Changing the format affects future approvals only.</p></form>`;openModal('Member unique-number format','Configure the automatic borrower/member number',body,`<button class="btn btn-neutral" id="cancelNumberSettings">Cancel</button><button class="btn btn-primary" id="saveNumberSettings">Save format</button>`);$('cancelNumberSettings').onclick=closeModal;$('saveNumberSettings').onclick=async()=>{const data=getFormData($('numberSettingsForm'));try{const {error}=await db.rpc('save_member_number_settings',{_organization_id:organization.id,_prefix:data.prefix,_format_pattern:data.format_pattern,_sequence_width:Number(data.sequence_width)});if(error)throw error;closeModal();toast('Member number format saved.');}catch(err){toast(err.message||'Unable to save number format.','error');}};}
function openCustomFieldsModal(){const body=`<div class="responsive-two"><div><div class="form-section"><h4>Add a custom field</h4><p>Custom fields are saved for this GORA organisation.</p></div><form id="customFieldForm" class="form-grid">${field('Field label','label','text','',{required:true})}${field('Field type','field_type','select','text',{required:true,choices:[{value:'text',label:'Text'},{value:'number',label:'Number'},{value:'date',label:'Date'},{value:'select',label:'Dropdown'},{value:'checkbox',label:'Checkbox'}]})}${field('Dropdown options (comma separated)','options','text','',{full:true,placeholder:'Only needed for dropdowns'})}<label class="check-row"><input type="checkbox" name="is_required"> Required for member registration</label><button class="btn btn-primary" type="submit">＋ Create field</button></form></div><div><div class="form-section"><h4>Current custom fields</h4><p>Fields already available on the registration form.</p></div>${customFields.length?customFields.map(f=>`<div class="restriction-item"><div><b>${esc(f.label)}</b><small>${esc(f.field_key)} · ${esc(f.field_type)}${f.is_required?' · Required':''}</small></div><button class="icon-btn deactivate-field" data-id="${f.id}">Deactivate</button></div>`).join(''):'<p class="muted">No custom fields created yet.</p>'}</div></div>`;openModal('Custom member fields','Add organization-specific borrower information',body,`<button class="btn btn-neutral" id="closeCustomFields">Close</button>`,true);$('closeCustomFields').onclick=closeModal;$('customFieldForm').onsubmit=async(e)=>{e.preventDefault();if(!roleCanManage()){toast('Manager permission required.','error');return;}const data=getFormData(e.target);const key=data.label.toLowerCase().trim().replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'').slice(0,49);if(!key){toast('Enter a valid field label.','error');return;}const options=data.field_type==='select'?data.options.split(',').map(x=>x.trim()).filter(Boolean):[];try{const {error}=await db.from('gora_member_custom_fields').insert({organization_id:organization.id,field_key:key,label:data.label.trim(),field_type:data.field_type,options,is_required:e.target.elements.is_required.checked,created_by:authUser.id});if(error)throw error;await loadReferenceData();openCustomFieldsModal();toast('Custom field created.');}catch(err){toast(err.message||'Unable to create custom field.','error');}};document.querySelectorAll('.deactivate-field').forEach(btn=>btn.onclick=async()=>{if(!roleCanManage())return;try{const {error}=await db.from('gora_member_custom_fields').update({is_active:false,updated_at:new Date().toISOString()}).eq('id',btn.dataset.id).eq('organization_id',organization.id);if(error)throw error;await loadReferenceData();openCustomFieldsModal();toast('Custom field deactivated.');}catch(err){toast(err.message,'error');}});}
function parseCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i],next=text[i+1];if(ch==='"'&&quoted&&next==='"'){cell+='"';i++;}else if(ch==='"'){quoted=!quoted;}else if(ch===','&&!quoted){row.push(cell);cell='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&next==='\n')i++;row.push(cell);cell='';if(row.some(v=>v.trim()!==''))rows.push(row);row=[];}else cell+=ch;}row.push(cell);if(row.some(v=>v.trim()!==''))rows.push(row);if(!rows.length)return[];const headers=rows.shift().map(h=>h.trim().toLowerCase());return rows.map(values=>Object.fromEntries(headers.map((h,i)=>[h,(values[i]||'').trim()])));}
function openCsvImportModal(){const body=`<div class="note-box">CSV import creates pending member records. The member-number sequence is assigned after approval. Include the columns <b>first_name</b> and <b>last_name</b>, or <b>business_name</b>. Phone, email, branch, chama and documents are optional. Include <b>savings_agreement_accepted</b> and <b>information_declaration_accepted</b> as TRUE only when the member has confirmed them.</div><form id="csvImportForm"><div class="form-field"><label>CSV file<input id="csvFile" type="file" accept=".csv,text/csv" required></label></div></form><div id="csvPreview" class="csv-preview"></div>`;openModal('Bulk borrower import','Import multiple members from an Excel-compatible CSV',body,`<button class="btn btn-neutral" id="cancelCsvImport">Cancel</button><button class="btn btn-primary" id="startCsvImport" disabled>Import members</button>`,true);$('cancelCsvImport').onclick=closeModal;$('csvFile').onchange=async(e)=>{const file=e.target.files[0];if(!file)return;const rows=parseCsv(await file.text());window.__goraCsvRows=rows;$('csvPreview').innerHTML=rows.length?`<div class="note-box">${rows.length} rows found. Preview of first 5:</div><pre>${esc(JSON.stringify(rows.slice(0,5),null,2))}</pre>`:'<p class="muted">No data rows found.</p>'; $('startCsvImport').disabled=!rows.length;};$('startCsvImport').onclick=async()=>{const rows=window.__goraCsvRows||[];if(!rows.length)return;const btn=$('startCsvImport');btn.disabled=true;let success=0,failed=0;const errors=[];for(let i=0;i<rows.length;i++){const r=rows[i];if(String(r.savings_agreement_accepted).toLowerCase()!=='true'||String(r.information_declaration_accepted).toLowerCase()!=='true'){failed++;errors.push(`Row ${i+2}: both declaration columns must be TRUE.`);continue;}const payload={...r,savings_agreement_accepted:true,information_declaration_accepted:true,custom_field_values:{}};try{if(r.custom_field_values)payload.custom_field_values=JSON.parse(r.custom_field_values);for(const key of ['branch_id','chama_group_id','loan_officer_id'])payload[key]=r[key]||null;const {error}=await db.rpc('register_member_v3',{_member_id:crypto.randomUUID(),_organization_id:organization.id,_payload:payload});if(error)throw error;success++;}catch(err){failed++;errors.push(`Row ${i+2}: ${err.message||'registration failed'}`);}}closeModal();toast(`CSV import complete: ${success} added, ${failed} failed.`,failed?'error':'success');if(errors.length)openModal('CSV import results','Some rows could not be imported',`<div class="warning-box">${errors.map(x=>`<div>${esc(x)}</div>`).join('')}</div>`,`<button class="btn btn-primary" id="closeImportResults">Close</button>`,true),$('closeImportResults').onclick=closeModal;membersPageIndex=0;await renderMembers();};}
async function exportMembersCsv(){try{const all=[];let offset=0,total=Infinity;while(offset<total){const rows=await safeQuery(db.rpc('search_members_v2',{_organization_id:organization.id,_search:memberSearch||null,_member_status:memberStatusFilter,_branch_id:branchFilter==='ALL'?null:branchFilter,_last_loan_status:lastLoanFilter,_limit:100,_offset:offset}));if(!rows?.length)break;total=Number(rows[0].total_count||0);all.push(...rows);offset+=rows.length;}const cols=['member_number','first_name','last_name','business_name','full_name','phone','email','address','gender','date_of_birth','status','last_loan_status','custom_field_values'];const csv=[cols.join(','),...all.map(r=>cols.map(c=>csvCell(c==='custom_field_values'?JSON.stringify(r[c]||{}):r[c])).join(','))].join('\r\n');downloadText(`gora_members_${todayLocal()}.csv`,csv,'text/csv;charset=utf-8;');toast(`${all.length} member records exported.`);}catch(err){toast(err.message||'Export failed.','error');}}
function csvCell(value){const s=String(value??'');return /[",\r\n]/.test(s)?`"${s.replace(/"/g,'""')}"`:s;}function downloadText(filename,text,type){const blob=new Blob(['\ufeff',text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url);}
async function contactSelected(channel){const ids=[...selectedMemberIds];if(!ids.length){toast('Select at least one member first.','error');return;}const rows=await safeQuery(db.from('members').select('id,full_name,phone,email').eq('organization_id',organization.id).in('id',ids));if(channel==='email'){const addresses=rows.map(r=>r.email).filter(Boolean);if(!addresses.length){toast('Selected members have no email addresses.','error');return;}location.href=`mailto:?bcc=${encodeURIComponent(addresses.join(','))}&subject=${encodeURIComponent('GORA Savings & Credit Group')}`;}else{const phones=rows.map(r=>r.phone).filter(Boolean);if(!phones.length){toast('Selected members have no phone numbers.','error');return;}location.href=`sms:${phones.join(',')}`;}toast('Your device messaging composer was opened. Messages are not sent automatically.');}
async function openMemberProfile(memberId,tab='Overview'){
 currentProfileId=memberId;currentProfileTab=tab;
 openModal('Member profile','Loading member records…','<div class="loading-panel">Loading member profile, loans and savings…</div>','',true);
 try{
  const member=await safeQuery(db.from('members').select('*').eq('organization_id',organization.id).eq('id',memberId).single());
  const [loans,accounts,restrictions,otherDocs]=await Promise.all([
   safeQuery(db.from('loan_accounts').select('id,loan_account_number,principal_amount,total_interest,total_repayment,status,disbursed_on,first_due_date,branch_id').eq('organization_id',organization.id).eq('member_id',memberId).order('created_at',{ascending:false})),
   safeQuery(db.from('savings_accounts').select('id,account_number,status,opened_at').eq('organization_id',organization.id).eq('member_id',memberId).order('opened_at',{ascending:false})),
   safeQuery(db.from('gora_member_restrictions').select('id,restriction_type,reason,starts_on,expires_on,is_active,created_at').eq('organization_id',organization.id).eq('member_id',memberId).order('created_at',{ascending:false})),
   safeQuery(db.from('gora_member_documents').select('id,document_type,original_filename,storage_path,mime_type,file_size,created_at').eq('organization_id',organization.id).eq('member_id',memberId).order('created_at',{ascending:false}))
  ]);
  const loanIds=(loans||[]).map(x=>x.id);
  const schedules=loanIds.length?await safeQuery(db.from('loan_schedule_balances').select('schedule_id,loan_account_id,installment_number,due_date,total_due,amount_paid,amount_outstanding,payment_status').eq('organization_id',organization.id).in('loan_account_id',loanIds).order('due_date')):[];
  const savingsBalances=accounts?.length?await safeQuery(db.rpc('get_savings_account_balances',{_organization_id:organization.id})):[];
  const accountIds=new Set((accounts||[]).map(x=>x.id));
  const balances=(savingsBalances||[]).filter(x=>accountIds.has(x.savings_account_id));
  const savingsTotal=balances.reduce((s,x)=>s+Number(x.posted_balance||0),0);
  const savingsTransactions=accountIds.size?await safeQuery(db.from('savings_transactions').select('transaction_type,amount,status').eq('organization_id',organization.id).in('savings_account_id',[...accountIds])):[];
  const postedDeposits=(savingsTransactions||[]).filter(x=>x.status==='POSTED'&&x.transaction_type==='DEPOSIT').reduce((s,x)=>s+Number(x.amount||0),0);
  const currentLoans=(loans||[]).filter(x=>x.status==='ACTIVE');
  const currentSchedules=(schedules||[]).filter(x=>currentLoans.some(l=>l.id===x.loan_account_id));
  const loanOutstanding=currentSchedules.reduce((s,x)=>s+Number(x.amount_outstanding||0),0);
  const installmentsPaid=currentSchedules.reduce((s,x)=>s+Number(x.amount_paid||0),0);
  const signedDocs={};
  for(const [key,path] of [['member_photo',member.member_photo_path],['id_front',member.national_id_front_path],['id_back',member.national_id_back_path],['kin_photo',member.next_of_kin_photo_path]]){
   if(path){const {data,error}=await db.storage.from('gora-member-documents').createSignedUrl(path,300);if(!error)signedDocs[key]=data.signedUrl;}
  }
  for(const doc of (otherDocs||[])){const {data,error}=await db.storage.from('gora-member-documents').createSignedUrl(doc.storage_path,300);if(!error)doc.signedUrl=data.signedUrl;}
  const officer=loanOfficers.find(x=>x.id===member.loan_officer_id);
  const branch=branches.find(x=>x.id===member.branch_id);
  const chama=chamas.find(x=>x.id===member.chama_group_id);
  const restricted=(restrictions||[]).some(r=>r.is_active&&r.starts_on<=todayLocal()&&(!r.expires_on||r.expires_on>=todayLocal()));
  window.__goraMemberProfile={member,loans:loans||[],schedules:schedules||[],accounts:accounts||[],balances,restrictions:restrictions||[],otherDocs:otherDocs||[],signedDocs,savingsTotal,postedDeposits,currentLoans,currentSchedules,loanOutstanding,installmentsPaid,officer,branch,chama,restricted};
  renderProfileModal();
 }catch(err){
  openModal('Member profile','Unable to load the complete profile',`<div class="warning-box">${esc(err.message||'Profile loading failed')}</div>`,`<button class="btn btn-primary" id="profileErrorClose">Close</button>`,true);
  $('profileErrorClose').onclick=closeModal;
 }function renderProfileModal(){const p=window.__goraMemberProfile;if(!p)return;const m=p.member;const activeRestrictions=p.restrictions.filter(r=>r.is_active&&r.starts_on<=todayLocal()&&(!r.expires_on||r.expires_on>=todayLocal()));const heroPhoto=p.signedDocs.member_photo?`<img src="${p.signedDocs.member_photo}" alt="Member photo">`:`<div class="profile-avatar">${esc(initials(m.full_name))}</div>`;const body=`<div class="profile-hero">${heroPhoto}<div><h2>${esc(m.business_name||m.full_name)}</h2><p>${esc(m.member_number||'Member number pending')} · ${esc(m.phone||'No phone number')}</p><div>${statusPill(m.status)} ${activeRestrictions.length?'<span class="pill restricted">RESTRICTED</span>':''}</div></div><div class="profile-hero-actions"><button class="btn btn-primary" id="profileAddLoan">＋ Add loan</button><button class="btn btn-teal" id="profileAddSavings">＋ Add savings</button></div></div><div class="profile-metrics"><div class="profile-metric"><span>Current loans</span><b>${number(p.currentLoans.length)}</b></div><div class="profile-metric"><span>Loan balance</span><b>${money(p.loanOutstanding)}</b></div><div class="profile-metric"><span>Savings balance</span><b>${money(p.savingsTotal)}</b></div><div class="profile-metric"><span>Paid amount</span><b>${money(p.installmentsPaid)}</b></div></div><div class="profile-tabs">${['Overview','Loans','Savings','Documents','Restrictions'].map(t=>`<button class="profile-tab ${currentProfileTab===t?'active':''}" data-profile-tab="${t}">${t}</button>`).join('')}</div><div id="profileTabContent">${profileTabContent(p,currentProfileTab)}</div>`;const footer=`${roleCanManage()?`<button class="btn btn-soft" id="editMemberBtn">Edit details</button>`:''}${roleCanApprove()&&m.status==='PENDING'?`<button class="btn btn-teal" id="approveMemberBtn">Approve &amp; generate number</button><button class="btn btn-danger" id="rejectMemberBtn">Reject</button>`:''}${roleCanManage()?`<button class="btn btn-neutral" id="transferBranchBtn">Move branch</button><button class="btn btn-purple" id="restrictionBtn">Add restriction</button>`:''}<button class="btn btn-neutral" id="borrowerPanelBtn">Borrower control panel</button><button class="btn btn-neutral" id="closeProfileBtn">Close</button>`;openModal('Member profile',`${m.member_number||'Pending number'} · ${esc(m.full_name)}`,body,footer,true);document.querySelectorAll('[data-profile-tab]').forEach(b=>b.onclick=()=>{currentProfileTab=b.dataset.profileTab;renderProfileModal();});$('closeProfileBtn').onclick=closeModal;if($('editMemberBtn'))$('editMemberBtn').onclick=()=>openEditMemberModal(m.id);$('profileAddLoan').onclick=()=>{closeModal();navigateFutureWithMember('Loan Applications',m.id);};$('profileAddSavings').onclick=()=>{closeModal();navigateFutureWithMember('Savings',m.id);};$('borrowerPanelBtn').onclick=()=>openBorrowerPanel(m.id);if($('approveMemberBtn'))$('approveMemberBtn').onclick=()=>approveMember(m.id);if($('rejectMemberBtn'))$('rejectMemberBtn').onclick=()=>rejectMember(m.id);if($('transferBranchBtn'))$('transferBranchBtn').onclick=()=>openBranchTransfer(m.id);if($('restrictionBtn'))$('restrictionBtn').onclick=()=>openRestrictionModal(m.id);if(currentProfileTab==='Documents'){const input=$('memberAdditionalFiles');if(input)input.onchange=async()=>{const files=[...(input.files||[])];let failed=0;for(const file of files){try{await saveGeneralMemberDocument(m.id,file,$('memberDocumentType').value||'OTHER');}catch(err){failed++;toast(err.message||'File upload failed.','error');}}await openMemberProfile(m.id,'Documents');if(!failed)toast(`${files.length} file(s) uploaded.`);};}}function profileTabContent(p,tab){const m=p.member;if(tab==='Overview'){const details=[['First name',m.first_name],['Last name',m.last_name],['Business name',m.business_name],['Title',m.title],['Email',m.email],['Mobile',m.phone],['National ID',m.national_id],['Date of birth',m.date_of_birth],['Gender',m.gender],['Address',m.address],['County',m.county],['Town',m.town],['Estate',m.estate],['Occupation',m.occupation],['Income source',m.income_source],['Branch',p.branch?.branch_name||m.branch_id],['Chama',p.chama?.group_name||m.chama_group_id],['Loan officer',p.officer?.full_name],['Next of kin',m.next_of_kin_name],['Relationship',m.next_of_kin_relationship],['Next-of-kin phone',m.next_of_kin_phone],['Registered',m.registration_date],['Registration fee',m.registration_fee_status]];return `<div class="detail-grid">${details.map(([l,v])=>`<div class="detail-item"><span>${esc(l)}</span><b>${esc(v||'—')}</b></div>`).join('')}</div><div class="profile-subhead">Custom member information</div>${Object.keys(m.custom_field_values||{}).length?`<div class="detail-grid">${Object.entries(m.custom_field_values).map(([k,v])=>`<div class="detail-item"><span>${esc(customFields.find(f=>f.field_key===k)?.label||k)}</span><b>${esc(typeof v==='object'?JSON.stringify(v):v)}</b></div>`).join('')}</div>`:'<p class="muted">No custom field values saved.</p>'}<div class="profile-subhead">Contact member</div><div class="message-actions">${m.phone?`<a class="btn btn-soft" href="sms:${esc(m.phone)}">SMS</a><a class="btn btn-teal" target="_blank" rel="noopener" href="${esc(whatsappUrl(m.phone))}">WhatsApp</a>`:''}${m.email?`<a class="btn btn-purple" href="mailto:${esc(m.email)}">Email</a>`:''}</div><div class="note-box">Branch transfer changes the member's current branch. Existing loans and transactions retain their original branch history.</div>`;}if(tab==='Loans'){return `<div class="profile-subhead">Loan accounts</div>${p.loans.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Loan number</th><th>Principal</th><th>Total repayment</th><th>Status</th><th>Disbursed</th></tr></thead><tbody>${p.loans.map(l=>`<tr><td>${esc(l.loan_account_number)}</td><td>${money(l.principal_amount)}</td><td>${money(l.total_repayment)}</td><td>${statusPill(l.status)}</td><td>${esc(l.disbursed_on||'—')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No loan accounts recorded for this member.</div>'}<div class="profile-subhead">Installments &amp; balances</div>${p.schedules.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Loan</th><th>Installment</th><th>Due date</th><th>Due</th><th>Paid</th><th>Balance</th><th>Status</th></tr></thead><tbody>${p.schedules.map(s=>`<tr><td>${esc(p.loans.find(l=>l.id===s.loan_account_id)?.loan_account_number||'—')}</td><td>${s.installment_number}</td><td>${esc(s.due_date)}</td><td>${money(s.total_due)}</td><td>${money(s.amount_paid)}</td><td>${money(s.amount_outstanding)}</td><td>${statusPill(s.payment_status)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No repayment schedule is recorded yet.</div>'}`;}if(tab==='Savings'){return `<div class="profile-metrics"><div class="profile-metric"><span>Posted savings balance</span><b>${money(p.savingsTotal)}</b></div><div class="profile-metric"><span>Total posted deposits</span><b>${money(p.postedDeposits)}</b></div><div class="profile-metric"><span>Savings accounts</span><b>${number(p.accounts.length)}</b></div><div class="profile-metric"><span>Shares paid</span><b>Not tracked yet</b></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Account number</th><th>Status</th><th>Posted balance</th><th>Opened</th></tr></thead><tbody>${p.accounts.length?p.accounts.map(a=>`<tr><td>${esc(a.account_number)}</td><td>${statusPill(a.status)}</td><td>${money(p.balances.find(b=>b.savings_account_id===a.id)?.posted_balance||0)}</td><td>${esc(String(a.opened_at||'').slice(0,10))}</td></tr>`).join(''):'<tr><td colspan="4"><div class="empty-state">No savings accounts found.</div></td></tr>'}</tbody></table></div><div class="note-box">Shares paid are not displayed as a financial figure because the current database has no separate share ledger. The Shares feature will be added with the Savings module; we will not treat ordinary savings deposits as shares.</div>`;}if(tab==='Documents'){const docs=[['Member photo','member_photo'],['ID front','id_front'],['ID back','id_back'],['Next-of-kin photo','kin_photo']];return `<div class="doc-grid">${docs.map(([label,key])=>`<div class="doc-card">${p.signedDocs[key]?`<img src="${p.signedDocs[key]}" alt="${esc(label)}"><a href="${p.signedDocs[key]}" target="_blank" rel="noopener">View securely</a>`:'<div class="empty-state">Not uploaded</div>'}<b>${esc(label)}</b></div>`).join('')}</div><div class="profile-subhead">Supporting files</div><div class="form-grid"><div class="form-field"><label>Document type<select id="memberDocumentType"><option value="OTHER">Other</option><option value="PROOF_OF_ADDRESS">Proof of address</option><option value="INCOME_PROOF">Proof of income</option><option value="BUSINESS_DOCUMENT">Business document</option><option value="CONSENT">Consent / agreement</option></select></label></div><div class="form-field"><label>Upload files<input id="memberAdditionalFiles" type="file" class="file-input" multiple accept=".pdf,.doc,.docx,.xls,.xlsx,.txt,image/jpeg,image/png,image/webp"></label><small class="small-note">PDF, Word, Excel, text or image · max 10 MB each</small></div></div>${p.otherDocs.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>File</th><th>Type</th><th>Uploaded</th><th>Size</th><th>Open</th></tr></thead><tbody>${p.otherDocs.map(d=>`<tr><td>${esc(d.original_filename)}</td><td>${esc(d.document_type.replaceAll('_',' '))}</td><td>${esc(String(d.created_at||'').slice(0,10))}</td><td>${number(Math.ceil(d.file_size/1024))} KB</td><td>${d.signedUrl?`<a href="${d.signedUrl}" target="_blank" rel="noopener">Open</a>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No supporting files uploaded.</div>'}<p class="small-note">Private document links expire after a short period.</p>`;}return `<div class="profile-subhead">Borrower restrictions</div>${p.restrictions.length?p.restrictions.map(r=>`<div class="restriction-item"><div><b>${esc(r.restriction_type.replaceAll('_',' '))} ${!r.is_active?statusPill('INACTIVE'):r.starts_on>todayLocal()?statusPill('PENDING'):statusPill('ACTIVE')}</b><small>${esc(r.reason)} · Start ${esc(r.starts_on)} ${r.expires_on?`· Ends ${esc(r.expires_on)}`:'· No expiry'}</small></div>${r.is_active&&roleCanManage()?`<button class="icon-btn remove-restriction" data-id="${r.id}">Remove</button>`:''}</div>`).join(''):'<p class="muted">No restrictions recorded.</p>'}`;}
function whatsappUrl(phone){let digits=String(phone||'').replace(/\D/g,'');if(digits.startsWith('0'))digits='254'+digits.slice(1);if(digits.startsWith('7')||digits.startsWith('1'))digits='254'+digits;return `https://wa.me/${digits}`;}
function navigateFutureWithMember(moduleName,memberId){document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.module===moduleName));$('pageTitle').textContent=moduleName;renderFutureModule(moduleName);const box=document.querySelector('.future-module');if(box){const p=window.__goraMemberProfile?.member;box.insertAdjacentHTML('beforeend',`<div class="success-box">Selected borrower: <b>${esc(p?.full_name||'Member')}</b> (${esc(p?.member_number||'pending number')}). This member context will carry into the ${esc(moduleName)} module when it is built.</div>`);}}
function openBorrowerPanel(memberId){const m=window.__goraMemberProfile?.member;if(!m)return;openModal('Borrower control panel','Member self-service view',`<div class="profile-hero"><div class="profile-avatar">${esc(initials(m.full_name))}</div><div><h2>${esc(m.full_name)}</h2><p>${esc(m.member_number||'Member number pending')}</p></div></div><div class="note-box">The borrower control panel will allow the member to view their account and submit loan applications online. The portal login and application workflow are scheduled for the Loan Applications module.</div><button class="btn btn-primary" id="panelApplyLoan">Apply for loan</button>`,`<button class="btn btn-neutral" id="panelClose">Close</button>`,false);$('panelClose').onclick=closeModal;$('panelApplyLoan').onclick=()=>{closeModal();navigateFutureWithMember('Loan Applications',memberId);};}
async function approveMember(memberId){if(!roleCanApprove()){toast('Manager permission required.','error');return;}if(!confirm('Approve this member and generate their unique number?'))return;try{const {data,error}=await db.rpc('approve_member_v2',{_member_id:memberId});if(error)throw error;toast(`Member approved. Number: ${data}`);closeModal();await renderMembers();}catch(err){toast(err.message||'Approval failed.','error');}}
async function rejectMember(memberId){const reason=prompt('Reason for rejecting this member application:');if(!reason||reason.trim().length<5){toast('Enter a rejection reason of at least 5 characters.','error');return;}try{const {error}=await db.rpc('reject_member',{_member_id:memberId,_reason:reason.trim()});if(error)throw error;closeModal();toast('Member application rejected.');await renderMembers();}catch(err){toast(err.message||'Rejection failed.','error');}}
function openEditMemberModal(memberId){
 const m=window.__goraMemberProfile?.member;if(!m)return;
 const officerChoices=[{value:'',label:'Unassigned'},...loanOfficers.map(o=>({value:o.id,label:o.full_name}))];
 const titleChoices=[{value:'',label:'Select title'},...['Mr','Mrs','Ms','Miss','Dr','Other'].map(x=>({value:x,label:x}))];
 const genderChoices=[{value:'',label:'Select gender'},...['FEMALE','MALE','OTHER','PREFER_NOT_TO_SAY'].map(x=>({value:x,label:x.replaceAll('_',' ')}))];
 const body=`<form id="editMemberForm"><div class="form-section"><h4>Identity &amp; contact</h4><p>Member number and approval status are protected and cannot be changed here.</p></div><div class="form-grid">${field('Title','title','select',m.title||'',{choices:titleChoices})}${field('First name','first_name','text',m.first_name||'')}${field('Last name','last_name','text',m.last_name||'')}${field('Business name','business_name','text',m.business_name||'')}${field('Mobile / phone','phone','tel',m.phone||'')}${field('Email address','email','email',m.email||'')}${field('Date of birth','date_of_birth','date',m.date_of_birth||'')}${field('Gender','gender','select',m.gender||'',{choices:genderChoices})}${field('National ID number','national_id','text',m.national_id||'')}${field('Address','address','text',m.address||'',{full:true})}${field('County','county','text',m.county||'')}${field('Town','town','text',m.town||'')}${field('Estate / village','estate','text',m.estate||'')}${field('Occupation','occupation','text',m.occupation||'')}${field('Income source','income_source','text',m.income_source||'')}${field('Description / notes','description','textarea',m.description||'',{full:true})}</div><div class="form-section"><h4>Next of kin &amp; officer</h4></div><div class="form-grid">${field('Next-of-kin name','next_of_kin_name','text',m.next_of_kin_name||'')}${field('Relationship','next_of_kin_relationship','text',m.next_of_kin_relationship||'')}${field('Next-of-kin phone','next_of_kin_phone','tel',m.next_of_kin_phone||'')}${field('Loan officer','loan_officer_id','select',m.loan_officer_id||'',{choices:officerChoices})}</div>${customFields.length?`<div class="form-section"><h4>Custom fields</h4></div><div class="form-grid">${customFields.map(f=>customFieldInput(f,m.custom_field_values?.[f.field_key]??'')).join('')}</div>`:''}<div class="note-box">Branch changes use the separate audited “Move branch” action. Chama assignment will be managed in the Chamas module.</div></form>`;
 openModal('Edit member details','Update borrower contact and profile information',body,`<button class="btn btn-neutral" id="cancelEditMember">Cancel</button><button class="btn btn-primary" id="saveEditMember">Save changes</button>`,true);
 $('cancelEditMember').onclick=()=>renderProfileModal();
 $('saveEditMember').onclick=async()=>{const form=$('editMemberForm');if(!form.reportValidity())return;const data=getFormData(form);const first=safeName(data.first_name),last=safeName(data.last_name),business=safeName(data.business_name);if(!(first&&last)&&!business){toast('Enter both first and last name, or a business name.','error');return;}const custom={};customFields.forEach(f=>{const el=form.elements[f.field_key]||form.elements[`custom_${f.field_key}`];if(f.field_type==='checkbox')custom[f.field_key]=!!el?.checked;else if(el&&el.value!=='')custom[f.field_key]=el.value;});const payload={...data,custom_field_values:custom,loan_officer_id:data.loan_officer_id||null};try{const {error}=await db.rpc('update_member_profile_v2',{_member_id:memberId,_payload:payload});if(error)throw error;toast('Member details updated.');await openMemberProfile(memberId);}catch(err){toast(err.message||'Member details could not be updated.','error');}};
}
function openBranchTransfer(memberId){if(!roleCanManage()){toast('Manager permission required.','error');return;}const choices=branches.map(b=>({value:b.id,label:b.branch_name}));openModal('Move member to another branch','Existing financial records keep their original branch history',`<form id="branchTransferForm">${field('Destination branch','branch_id','select','',{required:true,choices:[{value:'',label:'Select destination'},...choices]})}</form>`,`<button class="btn btn-neutral" id="cancelBranchTransfer">Cancel</button><button class="btn btn-primary" id="saveBranchTransfer">Transfer member</button>`);$('cancelBranchTransfer').onclick=closeModal;$('saveBranchTransfer').onclick=async()=>{const branchId=$('branchTransferForm').elements.branch_id.value;if(!branchId){toast('Choose a branch.','error');return;}try{const {error}=await db.rpc('transfer_member_branch_v2',{_member_id:memberId,_new_branch_id:branchId});if(error)throw error;closeModal();toast('Member branch updated.');await openMemberProfile(memberId);}catch(err){toast(err.message||'Branch transfer failed.','error');}};}
function openRestrictionModal(memberId){if(!roleCanManage()){toast('Manager permission required.','error');return;}const body=`<form id="restrictionForm" class="form-grid">${field('Restriction type','restriction_type','select','LOAN_BLOCK',{required:true,choices:[{value:'LOAN_BLOCK',label:'Block new loans'},{value:'ACCOUNT_HOLD',label:'Account hold'},{value:'CONTACT_ONLY',label:'Contact through officer only'},{value:'DOCUMENT_HOLD',label:'Document hold'}]})}${field('Start date','starts_on','date',todayLocal(),{required:true})}${field('Expiry date (optional)','expires_on','date')}${field('Reason','reason','textarea','',{required:true,full:true,placeholder:'Explain why this restriction is being applied'})}</form>`;openModal('Add borrower restriction','Restrictions are audited and can be removed by a manager',body,`<button class="btn btn-neutral" id="cancelRestriction">Cancel</button><button class="btn btn-danger" id="saveRestriction">Apply restriction</button>`);$('cancelRestriction').onclick=closeModal;$('saveRestriction').onclick=async()=>{const f=$('restrictionForm');if(!f.reportValidity())return;const d=getFormData(f);try{const {error}=await db.from('gora_member_restrictions').insert({organization_id:organization.id,member_id:memberId,restriction_type:d.restriction_type,reason:d.reason.trim(),starts_on:d.starts_on,expires_on:d.expires_on||null,created_by:authUser.id});if(error)throw error;closeModal();toast('Borrower restriction added.');await openMemberProfile(memberId);}catch(err){toast(err.message||'Restriction could not be saved.','error');}};}
// Remove active restrictions from the profile view using the manager-only RLS policy.
document.addEventListener('click',async(e)=>{const button=e.target.closest('.remove-restriction');if(!button)return;if(!confirm('Remove this restriction?'))return;try{const {error}=await db.rpc('remove_member_restriction_v2',{_restriction_id:button.dataset.id});if(error)throw error;toast('Restriction removed.');await openMemberProfile(currentProfileId,'Restrictions');}catch(err){toast(err.message||'Unable to remove restriction.','error');}});
// Restore saved connection values on the sign-in screen.
$('supabaseUrl').value=localStorage.getItem('gora2_url')||localStorage.getItem('gora_url')||'https://ptqenrbebssgfrhcuyuw.supabase.co';$('supabaseKey').value=localStorage.getItem('gora2_key')||localStorage.getItem('gora_key')||'';
// Resume an existing authenticated session when the public client settings are present.
(async()=>{if(!connect())return;try{const {data}=await db.auth.getSession();if(data?.session?.user)await finishLogin(data.session.user);}catch(e){console.warn('Session restore skipped:',e.message);}})();
    }
